import {universeCatalogPickerMarkup,EQUITY_ASSET_TYPES} from './universe-catalog-picker.mjs';
import {helpLabel} from './help-tooltip.mjs';
import {getInstrument} from '../domain/instruments.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const checked=value=>value?' checked':'';
const options=(rows,selected=[],query='')=>rows.map(([id,label])=>'<option value="'+esc(id)+'"'+(selected.includes(id)?' selected':query&&!label.toLowerCase().includes(query.toLowerCase())?' hidden':'')+'>'+esc(label)+'</option>').join('');
const check=(name,value,label,on)=>'<label class="universe-check"><input type="checkbox" name="'+name+'" value="'+esc(value)+'"'+checked(on)+'>'+esc(label)+'</label>';
const countLabel=name=>name==='explicitExcludeIds'?'명시 제외':'직접 선택';
const selectedMarkup=items=>items.map(item=>'<span class="catalog-selection-chip"><span title="'+esc(item.label)+'">'+esc(item.label)+'</span><button type="button" class="catalog-remove" data-studio-action="universe-remove" data-studio-id="'+esc(item.id)+'" aria-label="'+esc(item.label)+' 선택 해제">×</button></span>').join('');
const picker=(title,name,rows,selected,key,searches)=>{const query=searches[key]||'',match=label=>label.toLowerCase().includes(query.trim().toLowerCase()),count=rows.filter(([,label])=>match(label)).length;return '<div class="universe-local-picker" data-universe-picker data-universe-field-name="'+name+'"><select name="'+name+'" multiple hidden data-universe-values>'+options(rows,selected)+'</select><label class="field">'+esc(title)+' 검색<input type="search" data-universe-options-search data-universe-options-key="'+key+'" value="'+esc(query)+'" placeholder="종목명·거래쌍·거래소"></label><div class="catalog-selection" data-universe-selected role="group" aria-label="'+esc(title)+' 선택한 종목">'+selectedMarkup(rows.filter(([id])=>selected.includes(id)).map(([id,label])=>({id,label})))+'</div><p class="catalog-result-summary" data-universe-results-summary role="status">'+(query?'검색 결과 '+count+'개 · 전체 '+rows.length+'개':rows.length+'개 종목')+'</p><button type="button" class="button small universe-picker-skip" data-studio-action="universe-skip">검색 결과 건너뛰기</button><div class="catalog-results-region" role="group" aria-label="'+esc(title)+'">'+rows.map(([id,label])=>'<label class="catalog-result universe-local-option"'+(match(label)?'':' hidden')+'><input type="checkbox" data-universe-choice value="'+esc(id)+'" data-universe-label="'+esc(label)+'"'+checked(selected.includes(id))+'><span>'+esc(label)+'</span></label>').join('')+'<p class="catalog-empty" data-universe-empty role="status"'+(count?' hidden':'')+'>검색 조건에 맞는 종목이 없습니다. 검색어를 바꿔 보세요.</p></div><div class="actions"><small data-universe-selection-count tabindex="-1">'+countLabel(name)+' '+selected.length+'개</small><button type="button" class="button small" data-studio-action="universe-clear">'+esc(title)+' 해제</button></div></div>';};
const sourceTime=value=>value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))+' KST':'시각 미기록';
export function filterUniverseOptions(picker){
 const query=picker.querySelector('[data-universe-options-search]').value.trim().toLowerCase(),fields=[...picker.querySelectorAll('input[type="checkbox"]')];let matches=0;
 for(const field of fields){const match=field.dataset.universeLabel.toLowerCase().includes(query);field.closest('label').hidden=!match;if(match)matches++;}
 picker.querySelector('[data-universe-results-summary]').textContent=query?'검색 결과 '+matches+'개 · 전체 '+fields.length+'개':fields.length+'개 종목';picker.querySelector('[data-universe-empty]').hidden=matches>0;
}
export function updateUniverseSelectionCount(picker,source=null){
 const values=picker.querySelector('[data-universe-values]'),fields=[...picker.querySelectorAll('input[type="checkbox"]')];
 if(source===values){const ids=new Set([...values.selectedOptions].map(o=>o.value));for(const field of fields)field.checked=ids.has(field.value);}else{const ids=new Set(fields.filter(f=>f.checked).map(f=>f.value));for(const option of values.options)option.selected=ids.has(option.value);}
 const selected=[...picker.querySelectorAll('input[type="checkbox"]')].filter(field=>field.checked);picker.querySelector('[data-universe-selection-count]').textContent=countLabel(picker.dataset.universeFieldName)+' '+selected.length+'개';picker.querySelector('[data-universe-selected]').innerHTML=selectedMarkup(selected.map(field=>({id:field.value,label:field.dataset.universeLabel})));filterUniverseOptions(picker);
}
export function universePolicySummary(universe){
  if(!universe?.scopePolicy)return '<p class="tiny muted">개별 종목 '+(universe?.instrumentIds?.length||0)+'개 등록</p>';
  const p=universe.scopePolicy,r=universe.resolution;
  return '<section class="spaced"><h3>투자 범위</h3><p>'+esc([p.crypto.enabled?'코인 · '+p.crypto.exchanges.join(', ')+' · '+p.crypto.quoteMarkets.join(', ')+' · '+p.crypto.assetGroups.map(v=>v==='bitcoin'?'비트코인':'알트코인').join(', '):'',p.equities.enabled?'주식 · '+p.equities.markets.map(v=>v==='KR'?'한국':'미국').join(', ')+' · 선택 섹터 '+p.equities.sectorIds.length+'개':''].filter(Boolean).join(' / '))+'</p><p>허용 '+(r?.candidateIds?.length||0)+'개 · 직접 선택 '+p.explicitIncludeIds.length+'개 · 직접 제외 '+p.explicitExcludeIds.length+'개 · 최대 동시 보유 '+p.maxPositions+'개</p><p class="tiny muted">적용 자료 시점 '+esc(r?.asOf?new Date(r.asOf).toLocaleString('ko-KR'):'확인 필요')+'</p></section>';
}
export function universeEditorMarkup(catalog,{draft=null,mind=null,searches={}}={}){
  const old=catalog.policy,policy=draft||old?.scopePolicy||{},crypto=policy.crypto||{},equities=policy.equities||{},explicit=policy.explicitIncludeIds||old?.instrumentIds||[],excludes=policy.explicitExcludeIds||[];
  const instruments=[...(catalog.instruments||[])];for(const id of [...explicit,...excludes])if(!instruments.some(i=>i.id===id)){try{instruments.push(getInstrument(id));}catch{instruments.push({id,symbol:id,name:'원본 종목',venue:'정보 갱신 필요',assetClass:id.startsWith('crypto:')?'crypto':'equity'});}}const coins=instruments.filter(i=>i.assetClass==='crypto'),stocks=instruments.filter(i=>i.assetClass==='equity'),minimums=policy.minimumOrderAmounts||catalog.defaultMinimumOrderAmounts;
  const label=i=>i.symbol+' · '+i.name+' · '+i.venue,remote=!!catalog.search?.endpoint;
  const stocksPicker=remote?universeCatalogPickerMarkup({...catalog,instruments},{selected:explicit.filter(id=>id.startsWith('equity:')),query:searches.equities||''}):picker('주식 직접 선택','explicitIncludeIds',stocks.map(i=>[i.id,label(i)]),explicit.filter(id=>stocks.some(i=>i.id===id)),'equities',searches);
  const excludesPicker=remote?picker('제외할 코인','explicitExcludeIds',coins.map(i=>[i.id,label(i)]),excludes.filter(id=>id.startsWith('crypto:')),'excluded',searches)+universeCatalogPickerMarkup({...catalog,instruments},{key:'excludedEquities',name:'explicitExcludeIds',title:'제외할 주식',selected:excludes.filter(id=>id.startsWith('equity:')),query:searches.excludedEquities||''}):picker('제외 종목','explicitExcludeIds',instruments.map(i=>[i.id,label(i)]),excludes,'excluded',searches);
  const stockSource=remote?'<span>토스증권 '+Number(catalog.equities?.count||0).toLocaleString('ko-KR')+'개 종목 · '+esc(catalog.equities?.asOf?sourceTime(catalog.equities.asOf):'목록 수집 필요')+'</span>':'<span>등록 주식 '+stocks.length+'개 · 시장 자료 출처에 따른 범위</span>';
  const stockTypes=remote?'<input type="hidden" name="equityAssetTypesPresent" value="true"><div class="universe-checks">'+EQUITY_ASSET_TYPES.map(([value,label])=>check('equityAssetTypes',value,label,equities.assetTypes?.includes(value))).join('')+'</div>':'';
  const pinned=old?.resolution?.sourceRefs||[],upbitPin=pinned.find(ref=>ref.kind==='upbit-markets'),tossPin=pinned.find(ref=>ref.kind==='equity-sectors');
  const sourceDetails='정책에 고정한 자료 · 업비트 '+(upbitPin?sourceTime(upbitPin.asOf):'목록 없음')+' · 토스 '+(tossPin?sourceTime(tossPin.asOf):'자료 없음')+'. 이번 편집 자료 · 업비트 '+(catalog.upbit?.asOf?sourceTime(catalog.upbit.asOf):'수집 필요')+(catalog.upbit?.availableAt?' · 사용 가능 '+sourceTime(catalog.upbit.availableAt):'')+' · 토스 '+(catalog.sectorSnapshotRef?.availableAt?'사용 가능 '+sourceTime(catalog.sectorSnapshotRef.availableAt):'자료 연결 필요');
  const heading='<section class="full" data-universe-edit-context><strong>'+esc(mind?.name||'선택 마인드')+' · '+(Number.isSafeInteger(mind?.version)?'현재 발행 정책 v'+mind.version:'현재 발행 정책 정보 확인 필요')+'</strong><div class="actions"><small>초안 저장 후 발행</small>'+helpLabel('자료 기준 시점',sourceDetails)+'</div></section>';
  const coinCount=explicit.filter(id=>id.startsWith('crypto:')).length,stockCount=explicit.filter(id=>id.startsWith('equity:')).length;
  const sections=heading+'<input type="hidden" name="sectorLimits" value="'+esc(JSON.stringify(policy.sectorLimits||[]))+'">'+(policy.sectorLimits?.length?'<p class="tiny muted full">저장된 섹터별 보유 한도 '+policy.sectorLimits.length+'개 유지 · 정책 원본에서 편집</p>':'')+'<div class="full">'+helpLabel('투자 범위 설정','조건에 맞는 종목과 직접 선택한 종목을 합한 뒤 제외 종목과 유의·주의 조건을 적용합니다.')+'</div>'+
    '<details class="universe-fieldset full" data-universe-section="crypto"'+(crypto.enabled||coinCount||!stockCount?' open':'')+'><summary>코인 · 직접 선택 '+coinCount+'개</summary><fieldset><legend class="sr-only">코인</legend><section><h3>'+helpLabel('조건으로 선택','거래소, 결제 마켓, 자산 분류에 맞는 종목을 포함합니다.')+'</h3><div class="universe-checks">'+check('cryptoEnabled','true','분류로 선택',crypto.enabled)+check('exchanges','upbit','업비트',crypto.exchanges?.includes('upbit'))+check('exchanges','okx','OKX',crypto.exchanges?.includes('okx'))+'</div><div class="universe-grid"><div><span class="field-label">결제 마켓</span><div class="universe-checks">'+['KRW','BTC','USDT'].map(q=>check('quoteMarkets',q,q,crypto.quoteMarkets?.includes(q))).join('')+'</div></div><div><span class="field-label">'+helpLabel('자산 분류','비트코인은 BTC 자산, 알트코인은 BTC 이외의 코인입니다. BTC 마켓에서도 거래 자산을 기준으로 분류합니다.')+'</span><div class="universe-checks">'+check('assetGroups','bitcoin','비트코인',crypto.assetGroups?.includes('bitcoin'))+check('assetGroups','alt','알트코인',crypto.assetGroups?.includes('alt'))+'</div></div></div><div class="universe-checks">'+check('excludeWarnings','true','유의 종목 제외',crypto.excludeWarnings!==false)+check('excludeCautions','true','주의 신호 종목 제외',crypto.excludeCautions!==false)+'</div></section><section class="spaced"><h3>'+helpLabel('직접 선택','분류 조건에 관계없이 거래쌍을 추가합니다. 제외 종목과 유의·주의 조건은 함께 적용됩니다.')+'</h3>'+picker('코인 직접 선택','explicitIncludeIds',coins.map(i=>[i.id,label(i)]),explicit.filter(id=>coins.some(i=>i.id===id)),'crypto',searches)+'</section><div class="universe-source"><span>'+esc(catalog.upbit?.status==='READY'?'업비트 '+catalog.upbit.count+'개 거래쌍 · '+sourceTime(catalog.upbit.asOf):catalog.upbit?.status==='STALE'?'업비트 목록 갱신 필요':'업비트 목록 수집 필요')+'</span><button type="button" class="button" data-studio-action="universe-collect">거래쌍 새로고침</button></div></fieldset></details>'+
    '<details class="universe-fieldset full" data-universe-section="equities"'+(equities.enabled||stockCount?' open':'')+'><summary>주식 · 직접 선택 '+stockCount+'개</summary><fieldset><legend class="sr-only">주식</legend><div class="universe-checks">'+check('equityEnabled','true','시장·섹터로 선택',equities.enabled)+check('markets','KR','한국',equities.markets?.includes('KR'))+check('markets','US','미국',equities.markets?.includes('US'))+'</div>'+stockTypes+'<label class="field">'+helpLabel('섹터','선택한 섹터의 구성 종목을 사용합니다. 비워두면 등록된 시장 종목 전체를 사용합니다.')+'<select name="sectorIds" aria-label="섹터" multiple size="4"'+(!catalog.sectors?.length?' disabled':'')+'>'+options((catalog.sectors||[]).map(s=>[s.id,'　'.repeat(s.depth||0)+s.name]),equities.sectorIds||[])+'</select></label>'+(catalog.sectors?.length?'':'<p class="tiny muted" role="status">섹터 자료 연결 필요 · 개별 종목 선택 가능</p>')+''+check('includeRelatedEtfs','true','관련 ETF 포함',equities.includeRelatedEtfs)+stocksPicker+'<div class="universe-source">'+stockSource+'<div class="actions">'+(remote?'<button type="button" class="button" data-studio-action="stocks-collect"'+(catalog.toss?.collectAvailable===true||catalog.equities?.syncAvailable===true?'':' disabled')+'>전체 종목 새로고침</button>':'')+'<button type="button" class="button" data-studio-action="sector-collect"'+(catalog.toss?.collectAvailable===true?'':' disabled')+'>토스 섹터 가져오기</button><button type="button" class="button" data-studio-action="sector-import">자료 가져오기</button></div></div></fieldset></details>'+
    '<fieldset class="universe-fieldset full"><legend>운용 한도</legend><details data-universe-section="exclusions"><summary>제외 종목 · '+excludes.length+'개</summary>'+excludesPicker+'</details><label class="field">최대 동시 보유 종목<input name="maxPositions" type="number" min="1" max="500" step="1" value="'+esc(policy.maxPositions||old?.selection?.maxPositions||3)+'" required></label><label class="field">'+helpLabel('최소 시세 이력','이 값과 연결된 계산 노드가 요구하는 이력 중 더 긴 기간을 사용합니다. 거래가 없는 봉이 빠지면 확정 봉의 연속성을 확인합니다.')+'<input name="minHistoryBars" aria-label="최소 시세 이력" type="number" min="1" max="999" step="1" value="'+esc(draft?.minHistoryBars??old?.selection?.minHistoryBars??64)+'" required>봉</label><details data-universe-section="minimums"><summary>통화별 최소 주문 금액</summary><div class="universe-grid">'+['KRW','BTC','USDT','USD'].map(currency=>'<label class="field">최소 주문 금액 · '+currency+'<input name="minimum_'+currency+'" type="number" step="any" min="'+({KRW:5000,BTC:0.00005,USDT:0.5,USD:0.00000001}[currency])+'" value="'+esc(minimums?.[currency])+'" required></label>').join('')+'</div><div>'+helpLabel('계좌 통화 기준','최소 주문 금액은 해당 계좌의 통화 기준입니다. 통화별 잔고와 손익을 각각 관리합니다.')+'</div></details></fieldset>';
  return sections;
}
export function readUniverseForm(data){
  const values=key=>[...new Set(data.getAll(key))],history=data.has('minHistoryBars')?Number(data.get('minHistoryBars')):null;
  if(data.has('minHistoryBars')&&(!Number.isSafeInteger(history)||history<1||history>999))throw new Error('최소 시세 이력을 1~999봉의 정수로 입력하세요.');
  return {crypto:{enabled:data.has('cryptoEnabled'),exchanges:values('exchanges'),quoteMarkets:values('quoteMarkets'),assetGroups:values('assetGroups'),excludeWarnings:data.has('excludeWarnings'),excludeCautions:data.has('excludeCautions')},equities:{enabled:data.has('equityEnabled'),markets:values('markets'),sectorIds:values('sectorIds'),includeRelatedEtfs:data.has('includeRelatedEtfs'),...(data.has('equityAssetTypesPresent')?{assetTypes:values('equityAssetTypes')}:{})},explicitIncludeIds:values('explicitIncludeIds'),explicitExcludeIds:values('explicitExcludeIds'),maxPositions:Number(data.get('maxPositions')),...(history!==null?{minHistoryBars:history}:{}),sectorLimits:JSON.parse(data.get('sectorLimits')||'[]'),minimumOrderAmounts:Object.fromEntries(['KRW','BTC','USDT','USD'].map(c=>[c,Number(data.get('minimum_'+c))]))};
}
